   function value(card){if(card.rank==='A')return 11;if(['K','Q','J'].includes(card.rank))return 10;return Number(card.rank)}
   function total(hand){let sum=hand.reduce((n,c)=>n+value(c),0),aces=hand.filter(c=>c.rank==='A').length;while(sum>21&&aces){sum-=10;aces--}return sum}
   function blackjack(hand){return hand.length===2&&total(hand)===21}
   function cardNode(card,hidden=false){const el=document.createElement('div');el.className='playing-card'+(hidden?' back':'')+(!hidden&&['♥','♦'].includes(card.suit)?' red':'');if(hidden)return el;el.innerHTML=`<span class="corner">${card.rank}<span>${card.suit}</span></span><span class="suit-large">${card.suit}</span><span class="corner bottom">${card.rank}<span>${card.suit}</span></span>`;el.setAttribute('aria-label',`${card.rank} ${card.suit}`);return el}
-  function render(){ui.dealer.replaceChildren();ui.player.replaceChildren();dealer.forEach((c,i)=>ui.dealer.append(cardNode(c,!reveal&&phase==='playing'&&i===1)));player.forEach(c=>ui.player.append(cardNode(c)));ui.dealerScore.textContent=dealer.length?(reveal||phase!=='playing'?` · ${total(dealer)}`:` · ${value(dealer[0])} + ?`):'';ui.playerScore.textContent=player.length?` · ${total(player)}`:'';ui.bankroll.textContent=money(bankroll);ui.bet.textContent=money(bet);ui.deal.disabled=phase==='playing'||bankroll<bet;ui.deal.textContent=phase==='betting'?'Deal':'Next hand';ui.actions.style.display=phase==='playing'?'flex':'none';ui.hit.disabled=phase!=='playing';ui.stand.disabled=phase!=='playing';ui.double.disabled=phase!=='playing'||player.length!==2||bankroll<bet;document.querySelectorAll('.quick-bets button,.stepper').forEach(b=>b.disabled=phase==='playing'||bankroll===0);$('wins').textContent=wins;$('losses').textContent=losses;$('pushes').textContent=pushes;$('streak').textContent=streak>0?`+${streak}`:streak;ui.delta.textContent=lastDelta?(lastDelta>0?`+${money(lastDelta)}`:`−${money(-lastDelta)}`):'';ui.delta.style.color=lastDelta<0?'#e98a7f':'#8fd39e';}
+  function render(){ui.dealer.replaceChildren();ui.player.replaceChildren();dealer.forEach((c,i)=>ui.dealer.append(cardNode(c,!reveal&&phase==='playing'&&i===1)));player.forEach(c=>ui.player.append(cardNode(c)));ui.dealerScore.textContent=dealer.length?(reveal||phase!=='playing'?` · ${total(dealer)}`:` · ${value(dealer[0])} + ?`):'';ui.playerScore.textContent=player.length?` · ${total(player)}`:'';ui.bankroll.textContent=money(bankroll);ui.bet.textContent=money(bet);ui.deal.disabled=phase==='playing'||(phase==='betting'&&bankroll<bet);ui.deal.textContent=phase==='betting'?'Deal':'Next hand';ui.actions.style.display=phase==='playing'?'flex':'none';ui.hit.disabled=phase!=='playing';ui.stand.disabled=phase!=='playing';ui.double.disabled=phase!=='playing'||player.length!==2||bankroll<bet;document.querySelectorAll('.quick-bets button,.stepper').forEach(b=>b.disabled=phase==='playing'||bankroll===0);$('wins').textContent=wins;$('losses').textContent=losses;$('pushes').textContent=pushes;$('streak').textContent=streak>0?`+${streak}`:streak;ui.delta.textContent=lastDelta?(lastDelta>0?`+${money(lastDelta)}`:`−${money(-lastDelta)}`):'';ui.delta.style.color=lastDelta<0?'#e98a7f':'#8fd39e';}
   function message(main='',sub=''){ui.main.textContent=main;ui.sub.textContent=sub}
   function say(text){ui.status.textContent=text}
   function start(){if(phase==='playing'||bet>bankroll)return;if(!shoe.length)freshShoe();player=[draw(),draw()];dealer=[draw(),draw()];bankroll-=bet;lastDelta=0;phase='playing';reveal=false;message();say('Your move — hit, stand, or double down.');render();if(blackjack(player)||blackjack(dealer)){reveal=true;if(blackjack(player)&&blackjack(dealer))finish('push');else if(blackjack(player))finish('blackjack');else finish('lose') }}
   function finish(result){reveal=true;phase='done';if(result==='dealer'){const p=total(player),d=total(dealer);result=d>21||p>d?'win':p<d?'lose':'push'}let payout=0;if(result==='blackjack'){payout=bet*2.5;wins++;streak=streak>=0?streak+1:1;message('Blackjack!','Natural pays 3:2');say('A perfect start. The house pays 3 to 2.')}else if(result==='win'){payout=bet*2;wins++;streak=streak>=0?streak+1:1;message('You win','Nice hand.');say('Your hand beats the dealer.')}else if(result==='push'){payout=bet;pushes++;streak=0;message('Push','Your bet comes back.');say('A tie — your wager is returned.')}else{losses++;streak=streak<=0?streak-1:-1;message('Dealer wins','Better luck next hand.');say('The house takes this one.')}bankroll+=payout;lastDelta=payout-(result==='blackjack'?bet:bet);if(bankroll===0){say('You’re out of chips. Reset the table to keep playing.')}render()}
